examples.check:
bits = [1, 0, 1, 1, 0, 0, 1]
nrzl = [1 if b == 1 else -1 for b in bits]
for v in nrzl:
    print(v)
prev = 1
nrz_i = []
for b in bits:
    if b == 1:
        prev = -prev
    nrz_i.append(prev)
for v in nrz_i:
    print(v)
man = []
for b in bits:
    if b == 1:
        man.extend([-1, 1])
    else:
        man.extend([1, -1])
for v in man:
    print(v)
ami = []
sign = 1
for b in bits:
    if b == 1:
        ami.append(sign)
        sign = -sign
    else:
        ami.append(0)
for v in ami:
    print(v)
